<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$u=require_user($pdo);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$title=trim($_POST['title']??'');if($title==='')$error='Project title is required.';else{$q=$pdo->prepare('INSERT INTO research_projects(public_id,owner_user_id,title,description) VALUES(?,?,?,?)');$q->execute([ulid_like(),$u['id'],$title,trim($_POST['description']??'')?:null]);header('Location:/research.php');exit;}}
$q=$pdo->prepare('SELECT public_id,title,description,created_at FROM research_projects WHERE owner_user_id=? ORDER BY created_at DESC');$q->execute([$u['id']]);$projects=$q->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><title>Research · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body><header class="topbar"><a class="brand" href="/">Annotated</a><nav><a href="/">Home</a><a href="/logout.php">Sign out</a></nav></header><main class="layout"><section><h1>Research</h1><p>Organize annotations and sources into durable research projects.</p><?php if(!$projects):?><div class="card">No projects yet.</div><?php endif?><?php foreach($projects as $p):?><article class="card"><h3><?=h($p['title'])?></h3><p><?=h($p['description'])?></p><div class="meta">Created <?=h($p['created_at'])?></div></article><?php endforeach?></section><aside><div class="card"><h3>New project</h3><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><label>Title<input name="title" required></label><label>Description<textarea name="description" rows="4"></textarea></label><button>Create project</button></form></div></aside></main></body></html>
